import json,time,urllib.request,urllib.error,email.utils,datetime,os
BASE='http://localhost:8080'
token=None
stats={'requests':0,'refreshes':0,'rate_limits':0,'retries':0}
def request(path,auth=True):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token',False)['token'];stats['refreshes']+=1
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   stats['requests']+=1
   with urllib.request.urlopen(req,timeout=30) as r: return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode()
   if e.code==401 and auth:
    token=[REDACTED_SECRET]
   if e.code==429 or 500<=e.code<600:
    stats['retries']+=1
    delay=e.headers.get('Retry-After')
    if delay:
     try: delay=float(delay)
     except ValueError: delay=max(0,email.utils.parsedate_to_datetime(delay).timestamp()-time.time())
    else:
     try:
      data=json.loads(body);delay=float(data.get('retry_after',1))
     except Exception: delay=1
    if e.code==429:stats['rate_limits']+=1
    print('Retry',e.code,path,'after',delay,flush=True);time.sleep(delay);continue
   raise RuntimeError((path,e.code,body))
  except (urllib.error.URLError,TimeoutError,ConnectionError) as e:
   stats['retries']+=1;print('Retry transport',path,str(e),flush=True);time.sleep(1)
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
seen={};qualifying=[];duplicates=0;conflicts=0;pages=set();path='/orders?page=1'
while path:
 data=request(path)
 assert data['page'] not in pages
 pages.add(data['page'])
 for order in data['items']:
  oid=order['id']
  if oid in seen:
   duplicates+=1
   if seen[oid]"'!=order:conflicts+=1;raise RuntimeError('"'Conflicting duplicate '+str(oid))
   continue
  seen[oid]=order
  dt=datetime.datetime.fromisoformat(order['placed_at'].replace('Z','+00:00'))
  assert dt.tzinfo is not None
  if order['status']=='shipped' and start<=dt.astimezone(datetime.timezone.utc)<end:qualifying.append(order)
 print('Page',data['page'],'of',data['total_pages'],'unique',len(seen),'qualifying',len(qualifying),flush=True)
 path=data['next']
assert pages==set(range(1,data['total_pages']+1))
customers={};regions={r:0 for r in ['north','south','east','west']};offset_boundary=0
for order in qualifying:
 cid=order['customer_id']
 if cid not in customers:
  customers[cid]=request('/customers/'+str(cid))
 c=customers[cid]
 assert c['id']==cid and type(c['discount_pct']) is int and 0<=c['discount_pct']<=100
 assert type(order['amount_cents']) is int and order['amount_cents']>=0
 cents=(order['amount_cents']*(100-c['discount_pct'])+50)//100
 regions[c['region']]+=cents
 local_date=datetime.datetime.fromisoformat(order['placed_at']).date()
 if not datetime.date(2025,3,1)<=local_date<=datetime.date(2025,5,31):offset_boundary+=1
result={'total_cents':sum(regions.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
with open('/workspace/result.json','w') as f:json.dump(result,f,indent=2);f.write('\\n')
with open('/workspace/result.json') as f:check=json.load(f)
assert set(check)=={'total_cents','order_count','duplicates_skipped','by_region'}
assert set(check['by_region'])=={'north','south','east','west'}
assert all(type(v) is int for v in check['by_region'].values())
assert sum(check['by_region'].values())==check['total_cents']
print(json.dumps({'result':result,'stats':stats,'pages':len(pages),'unique_listed':len(seen),'customers':len(customers),'qualifying_local_date_outside_range':offset_boundary}),flush=True)
